package com.nuri.woorilink.dto;import com.nuri.woorilink.entity.RecallNotice;import java.time.LocalDate;import java.util.List;
public record RecallNoticeDto(Long id,String recallUid,String productName,String brandName,List<String>modelNames,List<String>barcodeNumbers,List<String>certNumbers,LocalDate publishDate,String defectDescription,String hazardDescription,String consumerAction,RecallNotice.ActionType actionType,String inquiryTel,String sourceName,String sourceUrl,List<String>imageUrls){public static RecallNoticeDto from(RecallNotice n){return n==null?null:new RecallNoticeDto(n.getId(),n.getRecallUid(),n.getProductName(),n.getBrandName(),n.getModelNames(),n.getBarcodeNumbers(),n.getCertNumbers(),n.getPublishDate(),n.getDefectDescription(),n.getHazardDescription(),n.getConsumerAction(),n.getActionType(),n.getInquiryTel(),n.getSourceName(),n.getSourceUrl(),n.getImageUrls());}}
